function dataUtf8(value) {
  const bytes=[];
  for(let i=0;i<value.length;i++){
    let code=value.charCodeAt(i);
    if(code>=0xd800&&code<=0xdbff){const next=value.charCodeAt(i+1);if(next>=0xdc00&&next<=0xdfff){code=0x10000+((code-0xd800)<<10)+(next-0xdc00);i++;}else code=0xfffd;}
    else if(code>=0xdc00&&code<=0xdfff)code=0xfffd;
    if(code<128)bytes.push(code);
    else if(code<2048)bytes.push(192|(code>>>6),128|(code&63));
    else if(code<65536)bytes.push(224|(code>>>12),128|((code>>>6)&63),128|(code&63));
    else bytes.push(240|(code>>>18),128|((code>>>12)&63),128|((code>>>6)&63),128|(code&63));
  }
  return new Uint8Array(bytes);
}

